-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Die aktuellen und älteren Versionshinweise wurden in allen zehn unterstützten Sprachen außer Englisch sprachlich überarbeitet, damit sie sich natürlicher lesen und leichter verständlich sind.","Der bisher fehlende Eintrag zu 7.4.4 ist wieder im Versionsverlauf und in den Änderungsprotokollen enthalten."},["title"]="Versionshinweise und Versionsverlauf"}},["version"]="8.0.2",["welcome"]="Die Versionshinweise wurden sprachlich überarbeitet. Außerdem haben wir einen fehlenden Eintrag im Versionsverlauf ergänzt."},["esES"]={["sections"]={{["items"]={"Las notas de actualización, tanto actuales como antiguas, se han revisado en los diez idiomas disponibles además del inglés para que resulten más claras y naturales.","Hemos recuperado la entrada de la versión 7.4.4, que faltaba en el historial de versiones y en los registros de cambios. Ya puedes volver a consultarla."},["title"]="Notas de actualización e historial de versiones"}},["version"]="8.0.2",["welcome"]="Hemos revisado las notas de actualización para que sean más claras y naturales, y recuperado una entrada que faltaba en el historial de versiones."},["esMX"]={["sections"]={{["items"]={"Revisamos la redacción de las notas actuales y anteriores en los diez idiomas disponibles además del inglés para que sean más claras y naturales.","Recuperamos la entrada 7.4.4 que faltaba en el historial de lanzamientos y en los registros de cambios. Ya pueden consultarla."},["title"]="Notas de actualización e historial"}},["version"]="8.0.2",["welcome"]="Las notas de actualización ahora se leen con más claridad y naturalidad. También recuperamos una entrada que faltaba en el historial de lanzamientos."},["frFR"]={["sections"]={{["items"]={"Les notes de mise à jour actuelles et anciennes ont été réécrites dans les dix langues prises en charge autres que l’anglais, pour une lecture plus fluide et plus claire.","L’entrée manquante de la version 7.4.4 a été rétablie dans l’historique des versions consultable et dans les journaux des modifications."},["title"]="Notes de mise à jour et historique des versions"}},["version"]="8.0.2",["welcome"]="Les notes de mise à jour de QuestTogether sont plus claires, et l’historique des versions retrouve une entrée manquante."},["itIT"]={["sections"]={{["items"]={"Abbiamo rivisto le note di aggiornamento attuali e passate in tutte le dieci lingue supportate oltre all'inglese, per renderle più naturali e facili da leggere.","La voce mancante della versione 7.4.4 è di nuovo consultabile nella cronologia delle versioni e nei registri delle modifiche."},["title"]="Note di aggiornamento e cronologia"}},["version"]="8.0.2",["welcome"]="Le note di aggiornamento sono più chiare e scorrevoli, e la cronologia delle versioni torna a includere una voce mancante."},["koKR"]={["sections"]={{["items"]={"영어를 제외한 지원 언어 10개 모두에서 최신 및 이전 업데이트 안내를 더 자연스럽고 알기 쉽게 다듬었습니다.","누락되었던 7.4.4 항목을 출시 기록과 변경 내역에 복원해 다시 찾아볼 수 있습니다."},["title"]="업데이트 안내와 출시 기록"}},["version"]="8.0.2",["welcome"]="한국어를 비롯한 지원 언어의 업데이트 안내를 더 자연스럽고 읽기 쉽게 다듬고, 출시 기록에서 빠졌던 항목을 복원했습니다."},["ptBR"]={["sections"]={{["items"]={"Revisamos as notas de atualização atuais e antigas nos dez idiomas disponíveis além do inglês para deixar os textos mais claros e naturais.","Restauramos a entrada 7.4.4, que estava faltando no histórico de lançamentos disponível para consulta e nos registros de alterações."},["title"]="Notas de atualização e histórico"}},["version"]="8.0.2",["welcome"]="As notas de atualização estão mais claras e naturais, e o histórico de lançamentos voltou a incluir uma entrada que estava faltando."},["ruRU"]={["sections"]={{["items"]={"Описания текущего и прошлых обновлений отредактированы на всех десяти поддерживаемых языках, кроме английского. Формулировки стали яснее и естественнее, а исходный смысл сохранён.","В историю выпусков и журналы изменений возвращена пропущенная запись об обновлении 7.4.4. Теперь её снова можно просмотреть."},["title"]="Описания обновлений и история выпусков"}},["version"]="8.0.2",["welcome"]="Описания обновлений стали понятнее, а в истории выпусков восстановлена пропущенная запись."},["zhCN"]={["sections"]={{["items"]={"润色了全部十种受支持的非英语语言的更新说明，涵盖当前及历史内容，让文字更自然、清楚。各次更新的原意保持不变。","补回了缺失的 7.4.4 历史条目，现在可以在发布历史和更新日志中查阅。"},["title"]="更新说明与发布历史"}},["version"]="8.0.2",["welcome"]="本次更新润色了多语言更新说明，让内容更自然易读，并补回了缺失的发布历史记录。"},["zhTW"]={["sections"]={{["items"]={"已潤飾全部十種支援的非英語語言更新說明，涵蓋本次與過往的更新內容，讓文字更通順、意思更清楚。各次更新的原意維持不變。","已補回缺漏的 7.4.4 更新紀錄，現在可在發布歷史與變更紀錄中查閱。"},["title"]="更新說明與發布歷史"}},["version"]="8.0.2",["welcome"]="這次更新潤飾了多語言更新說明，讓內容更自然易讀，也補回了發布歷史中缺漏的紀錄。"}}
